//
// Where Enzan finds its parts (DESIGN_GUIDE.md section 11.5). The relative paths are generated by
// CMake, so these tests check its configure step too: that the paths compiled in lead, from an
// installation's bin/, to where the install rules put each part, and, from the build tree's, to
// where the build did.

#include "common/Installation.h"

#include <gtest/gtest.h>

#include <filesystem>
#include <system_error>

namespace {

namespace fs = std::filesystem;

/// The prefix of an installation, as `cmake --install --prefix /opt/enzan/1.0` would lay it out.
fs::path prefix() {
    return "/opt/enzan/1.0";
}

TEST(Installation, TheProgramDirectoryIsWhereThisTestIs) {
    const fs::path directory = enzan::programDirectory();
    ASSERT_FALSE(directory.empty());
    std::error_code failure;
    EXPECT_TRUE(fs::equivalent(directory, ENZAN_TEST_BUILD_BINDIR, failure))
        << directory << " is not " << ENZAN_TEST_BUILD_BINDIR;
}

TEST(Installation, TheFrontEndIsWhereAnInstallationPutsIt) {
    EXPECT_EQ(enzan::frontEndProgram(prefix() / ENZAN_TEST_INSTALL_BINDIR),
              prefix() / ENZAN_TEST_INSTALL_LIBEXECDIR / "enzan-gui");
}

TEST(Installation, TheVhdlLibrariesAreWhereAnInstallationPutsThem) {
    EXPECT_EQ(enzan::vhdlLibraryDirectory(prefix() / ENZAN_TEST_INSTALL_BINDIR),
              prefix() / ENZAN_TEST_INSTALL_VHDLDIR);
}

TEST(Installation, AMovedInstallationIsFollowed) {
    const fs::path moved = "/home/someone/tools/enzan";
    EXPECT_EQ(enzan::frontEndProgram(moved / ENZAN_TEST_INSTALL_BINDIR),
              moved / ENZAN_TEST_INSTALL_LIBEXECDIR / "enzan-gui");
}

TEST(Installation, NoProgramDirectoryLeadsNowhere) {
    EXPECT_TRUE(enzan::frontEndProgram({}).empty());
    EXPECT_TRUE(enzan::vhdlLibraryDirectory({}).empty());
}

// The build tree is laid out as an installation is, so the same paths find this build's own parts
// from the directory its executables are in.

#ifdef ENZAN_TEST_FRONT_END
TEST(Installation, TheBuildTreesFrontEndIsFound) {
    std::error_code failure;
    EXPECT_TRUE(fs::equivalent(enzan::frontEndProgram(enzan::programDirectory()),
                               ENZAN_TEST_FRONT_END, failure))
        << enzan::frontEndProgram(enzan::programDirectory()) << " is not " << ENZAN_TEST_FRONT_END;
}
#endif

#ifdef ENZAN_TEST_VHDL_LIBRARIES
TEST(Installation, TheBuildTreesVhdlLibrariesAreFound) {
    std::error_code failure;
    EXPECT_TRUE(fs::equivalent(enzan::vhdlLibraryDirectory(enzan::programDirectory()),
                               ENZAN_TEST_VHDL_LIBRARIES, failure))
        << enzan::vhdlLibraryDirectory(enzan::programDirectory()) << " is not "
        << ENZAN_TEST_VHDL_LIBRARIES;
}
#endif

} // namespace
